contract InvMutTest {
  C c;
  constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
  function test(uint256 amt) public {
    require(msg.sender == c.owner());
    require(amt > 0);
    uint256 before = c.totalSupply(); if (__ESBMC_reverted()) return;
    c.mintToken(address(this), amt); if (__ESBMC_reverted()) return;
    assert(c.totalSupply() == before + amt);
  }
  receive() external payable {}
  fallback() external payable {}
}

