pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _test(uint256 amt) internal {
        vm.assume(msg.sender == c.owner());
        vm.assume(amt > 0);
        uint256 before;
        try c.totalSupply() returns (uint256 __r) { before = __r; } catch { return; }
        try c.mintToken(address(this), amt) {} catch { return; }
        assertTrue(c.totalSupply() == before + amt);
    }

    function testFuzz_test(uint256 amt) public {
        _test(amt);
    }

    receive() external payable {}

    fallback() external payable {}
}
